        u(.high, "동사·준동사 구분", [10], ["동사와 준동사", "준동사", "본동사 찾기", "동사 준동사 구분", "동사 자리 준동사 자리"],
          summary: "한 절에는 동사가 하나 있어야 해요. 이미 동사가 있는 자리에 또 동사가 오면 준동사(to부정사·동명사·분사)로 바꾸고, 동사가 없으면 동사를 써야 해요.",
          points: ["절의 수 = 동사의 수 (접속사·관계사가 하나 늘면 동사도 하나 늘어요)",
                   "주어 자리에 동사가 오면 동명사·to부정사로: Swim is fun (×) → Swimming is fun",
                   "명사를 꾸미는 자리는 분사: the boy plays soccer is ~ (×) → playing",
                   "수식어(전치사구·관계절·분사구)를 걷어 내고 주어와 진짜 동사를 먼저 찾아요"],
          examples: ["The girl wearing a red dress is my sister. → 빨간 드레스를 입은 소녀가 내 여동생이에요.", "Learning English takes time. → 영어를 배우는 데는 시간이 걸려요.",
                     "The students who passed the test were happy. → 시험에 통과한 학생들은 기뻤어요."],
          traps: ["접속사·관계사 없이 동사 두 개 (×)", "긴 주어 뒤의 진짜 동사 찾기", "목적을 나타내는 자리는 to부정사: went to the store to buy"],
          items: [
            b("The man ___ next to me on the bus was very kind.", "sitting", ["sat", "sits", "was sitting"], "진짜 동사는 was → 명사를 꾸미는 분사"),
            b("___ regularly is good for your health.", "Exercising", ["Exercise is", "Exercised", "Exercises"], "주어 자리 → 동명사"),
            b("The students ___ the contest will get a prize.", "winning", ["win", "won", "wins"], "진짜 동사는 will get → 명사를 꾸미는 분사"),
            b("The boy who lives next door ___ a famous singer.", "is", ["being", "to be", "been"], "관계절(who lives next door) 뒤의 진짜 동사 자리"),
            b("I saw a dog ___ across the road.", "running", ["ran", "runs", "was running"], "지각동사의 목적격보어 → 준동사(-ing)"),
            b("There are many people ___ for the bus.", "waiting", ["wait", "waited", "are waiting"], "명사(people)를 꾸미는 분사(능동)"),
            b("The books on the shelf ___ old.", "are", ["being", "to be", "is"], "진짜 주어 books(복수) → are"),
            b("___ the test, he studied all night.", "To pass", ["Pass", "Passed", "Passes"], "목적(~하기 위해) → to부정사"),
            fx("The girl talks to my mom is my teacher.", "talks", "talking", "동사(is)가 이미 있으니 명사를 꾸미는 분사로", alt: ["who talks"]),
            fx("Read books is my hobby.", "Read", "Reading", "주어 자리 → 동명사", alt: ["To read"]),
            fx("The people lived in this village are kind.", "lived", "living", "동사(are)가 이미 있으니 분사로", alt: ["who live"]),
            fx("He went to the store bought some milk.", "bought", "to buy", "목적(~하기 위해) → to부정사"),
            fx("The letter writing in English was hard to read.", "writing", "written", "편지가 쓰인 것(수동) → 과거분사"),
            ox("The car parked in front of my house is my uncle's.", true, "parked(분사) + is(진짜 동사)"),
            ox("Taking a walk after dinner helps me sleep.", true, "동명사 주어 + helps(진짜 동사)"),
            ox("The boy broke the window ran away.", false, "동사가 둘: The boy who broke the window ran away."),
            rl("접속사나 관계사 없이 한 문장에 동사가 두 개 올 수 없다.", true, "절의 수 = 동사의 수예요."),
            rl("주어 자리에는 동사원형을 그대로 쓸 수 있다.", false, "주어 자리에는 동명사나 to부정사를 써요.")
          ]),

        u(.high, "관계사 심화", [10, 20], ["전치사 + 관계대명사", "계속적 용법", "복합관계사", "whoever whatever", "관계대명사의 계속적 용법", "복합관계대명사", "복합관계부사"],
          summary: "고등 관계사는 '전치사 + 관계대명사', 쉼표 뒤의 계속적 용법, -ever가 붙은 복합관계사를 다뤄요.",
          points: ["전치사 + 관계대명사: the house in which I live (전치사 뒤에는 that을 쓰지 않아요, 뒤는 완전한 문장)",
                   "계속적 용법: 쉼표 + who/which (that은 쓰지 않음), which는 앞 문장 전체를 받을 수 있어요",
                   "복합관계대명사: whoever(누구든지), whatever(무엇이든지), whichever",
                   "복합관계부사: whenever(언제든지), wherever(어디든지), however + 형용사(아무리 ~해도)"],
          examples: ["This is the house in which I was born. → 이것이 내가 태어난 집이에요.", "He said nothing, which made me angry. → 그는 아무 말도 하지 않았고, 그것이 나를 화나게 했어요.",
                     "Whoever comes first will get a prize. → 먼저 오는 사람은 누구든지 상을 받을 거예요."],
          traps: ["쉼표 뒤 that (×)", "in that (×) → in which", "However hard you try(아무리 열심히 해도): however 뒤 형용사·부사 먼저"],
          covers: ["공통영어|관계사"],
          items: [
            b("This is the house ___ which I was born.", "in", ["on", "to", "by"], "be born in a house → in which"),
            b("The man to ___ I spoke was very polite.", "whom", ["who", "that", "which"], "전치사 뒤 사람 관계대명사 → whom"),
            b("I have two sisters, ___ live in Seoul.", "who", ["that", "which", "whom"], "계속적 용법(쉼표 뒤)에는 that을 쓰지 않아요."),
            b("He passed the exam, ___ surprised everyone.", "which", ["that", "what", "who"], "앞 문장 전체를 받는 계속적 용법 which"),
            b("___ comes first will get a prize.", "Whoever", ["Who", "Whatever", "Whomever"], "whoever: ~하는 사람은 누구든지", ko: "먼저 오는 사람은 누구든지 상을 받을 거예요."),
            b("You can choose ___ you like.", "whatever", ["however", "whenever", "wherever"], "whatever: ~하는 것은 무엇이든지", ko: "네가 좋아하는 것은 무엇이든 골라도 돼."),
            b("___ hard you try, you can't finish it in a day.", "However", ["Whatever", "Whenever", "Although"], "however + 형용사/부사: 아무리 ~해도"),
            b("Call me ___ you need help.", "whenever", ["whatever", "whoever", "however"], "whenever: ~할 때는 언제든지"),
            b("This is the pen with ___ he wrote the novel.", "which", ["that", "what", "whom"], "전치사 + which (전치사 뒤 that ×)"),
            fx("I know a girl, that speaks three languages.", "that", "who", "계속적 용법에는 that을 쓰지 않아요."),
            fx("This is the town in that I grew up.", "that", "which", "전치사 뒤에는 that을 쓰지 않아요."),
            fx("Whatever wants to join the club is welcome.", "Whatever", "Whoever", "사람 → whoever(누구든지)"),
            fx("He lent me some money, that was very kind of him.", "that", "which", "앞 문장을 받는 계속적 용법은 which"),
            fx("This is the chair on which he sat on.", "sat on", "sat", "전치사가 관계대명사 앞으로 갔으니 뒤에 또 쓰지 않아요."),
            ox("The hotel at which we stayed was clean.", true, "전치사 + 관계대명사 + 완전한 문장"),
            ox("She has a son, who is a doctor.", true, "계속적 용법: 아들이 하나 있는데, 그는 의사예요"),
            ox("Wherever you go, I will follow you.", true, "wherever: 어디로 ~하든지"),
            ox("The reason for that he left is unknown.", false, "전치사 뒤에는 that을 쓰지 않아요: for which"),
            rl("관계대명사의 계속적 용법에는 that을 쓸 수 없다.", true, "쉼표 뒤에는 who/which를 써요."),
            rl("whoever는 '누구든지'라는 뜻의 복합관계대명사이다.", true, "Whoever comes ~처럼 써요."),
            rl("전치사 + 관계대명사 뒤에는 목적어가 빠진 불완전한 문장이 온다.", false, "전치사 + 관계대명사 뒤에는 완전한 문장이 와요."),
            mn("However tired you are, you should finish it.", "아무리 피곤해도 그것을 끝내야 해요.", ["피곤하니까 그것을 끝내지 않아도 돼요.", "피곤할 때마다 그것을 끝내야 해요.", "얼마나 피곤한지 말해 줘요."], "however + 형용사: 아무리 ~해도")
          ]),

        u(.high, "가정법", [10, 20], ["가정법 심화", "혼합 가정법", "without 가정법", "but for", "It's time 가정법", "if 생략 가정법"],
          summary: "고등 가정법은 혼합 가정법, Without/But for, if를 생략한 도치, It's time + 과거, as if의 시제 차이를 다뤄요.",
          points: ["혼합 가정법: If + had p.p.(과거 사실의 반대), 주어 + would + 동사원형 + now(현재 결과)",
                   "Without / But for + 명사 = If it were not for(현재) / If it had not been for(과거)",
                   "if 생략 → 도치: Were I rich = If I were rich / Had I known = If I had known",
                   "It's (high) time + 주어 + 과거동사: 이제 ~해야 할 때다",
                   "as if + 과거(주절과 같은 때) / as if + had p.p.(주절보다 앞선 때)"],
          examples: ["If I had taken the medicine, I would feel better now. → 그때 약을 먹었더라면 지금 몸이 나을 텐데.",
                     "Without your help, I couldn't finish it. → 네 도움이 없다면 그것을 끝낼 수 없을 텐데.", "It's time you went to bed. → 이제 잘 시간이야."],
          traps: ["혼합 가정법은 now 같은 현재 표시를 단서로", "It's time 뒤 동사는 과거형 (should + 동사원형도 가능)", "Had I known (Have I known ×)"],
          covers: ["공통영어|가정법"],
          items: [
            b("If I had studied harder then, I ___ a college student now.", "would be", ["would have been", "will be", "am"], "혼합 가정법: If + had p.p., would + 동사원형 + now"),
            b("___ your advice, I would have failed.", "Without", ["With", "Because", "Unless"], "Without ~ = If it had not been for ~", ko: "네 조언이 없었다면 나는 실패했을 거야."),
            b("If it ___ not for water, nothing could live.", "were", ["is", "had", "was being"], "If it were not for ~: ~이 없다면 (현재)"),
            b("___ I rich, I would buy a big house.", "Were", ["Am", "Was", "Had"], "if 생략 도치: Were I rich = If I were rich"),
            b("___ I known the truth, I would have told you.", "Had", ["Have", "Did", "Were"], "if 생략 도치: Had I known = If I had known"),
            b("It's time you ___ to bed.", "went", ["go", "going", "have gone"], "It's time + 주어 + 과거동사", alt: ["should go"]),
            b("She talks as if she ___ in London before.", "had lived", ["lives", "live", "will live"], "주절보다 앞선 때 → as if + had p.p."),
            b("___ the rain, we could have played soccer.", "But for", ["With", "Because", "Unless"], "But for ~ = If it had not been for ~", ko: "비가 오지 않았다면 우리는 축구를 할 수 있었을 텐데."),
            tr("if를 생략해 바꿀 때 빈칸에 알맞은 말은?", "If I had known her address, I would have written to her.", "___ her address, I would have written to her.", "Had I known", ["I had known", "Have I known", "Did I know"], "if 생략 → Had + 주어 + p.p."),
            tr("가정법으로 바꿀 때 빈칸에 알맞은 말은?", "As I didn't eat breakfast, I am hungry now.", "If I had eaten breakfast, I ___ hungry now.", "wouldn't be", ["wouldn't have been", "won't be", "am not"], "혼합 가정법: 과거의 반대 → 지금의 결과", alt: ["would not be"]),
            tr("같은 뜻이 되도록 바꿀 때 빈칸에 알맞은 말은?", "Without music, life would be boring.", "If it ___ not for music, life would be boring.", "were", ["is", "had been", "was being"], "Without(현재) = If it were not for"),
            fx("If I had slept enough last night, I would have felt fine now.", "would have felt", "would feel", "now(현재 결과) → 혼합 가정법: would + 동사원형"),
            fx("Have I known the news, I would have called you.", "Have", "Had", "if 생략 도치: Had I known"),
            fx("It's time we start the meeting.", "start", "started", "It's time + 주어 + 과거동사", alt: ["should start"]),
            fx("Without your help, I can't have finished the project.", "can't", "couldn't", "가정법 과거완료 주절: couldn't have p.p."),
            fx("Was I you, I would accept the offer.", "Was", "Were", "if 생략 도치: Were I you"),
            ox("Were I a bird, I could fly over the sea.", true, "Were I = If I were"),
            ox("If it had not been for his help, I would have lost my way.", true, "If it had not been for ~: ~이 없었다면 (과거)"),
            ox("It's high time you cleaned your room.", true, "It's high time + 주어 + 과거동사"),
            rl("Without ~은 If it were not for ~ 또는 If it had not been for ~로 바꿀 수 있다.", true, "현재는 were not, 과거는 had not been"),
            rl("혼합 가정법은 'If + 과거동사, 주어 + would have p.p.' 형태로만 쓴다.", false, "흔히 If + had p.p., 주어 + would + 동사원형 (+ now)이에요."),
            mn("If I had listened to you, I wouldn't be in trouble now.", "내가 네 말을 들었더라면 지금 곤란하지 않을 텐데.",
               ["내가 네 말을 들어서 지금 곤란하지 않아요.", "네 말을 들으면 곤란해질 거예요.", "내가 네 말을 들었지만 지금 곤란해요."], "혼합 가정법: 과거 사실의 반대 → 현재 결과")
          ]),

        u(.high, "조동사+have p.p.", [10, 20], ["must have p.p.", "should have p.p.", "조동사 have p.p.", "과거 추측", "조동사 + have p.p.", "can't have p.p."],
          summary: "조동사 + have p.p.는 과거의 일에 대한 추측이나 후회를 나타내요.",
          points: ["must have p.p.: ~했음에 틀림없다 (강한 추측)", "can't have p.p.: ~했을 리가 없다", "may/might have p.p.: ~했을지도 모른다",
                   "should have p.p.: ~했어야 했는데 (안 했다, 후회) / shouldn't have p.p.: ~하지 말았어야 했는데",
                   "could have p.p.: ~할 수도 있었는데 / need not have p.p.: ~할 필요가 없었는데"],
          examples: ["He must have been tired. → 그는 피곤했음에 틀림없어요.", "She can't have said that. → 그녀가 그런 말을 했을 리가 없어요.",
                     "I should have studied harder. → 더 열심히 공부했어야 했는데."],
          traps: ["must have p.p.(과거 추측) vs had to(과거 의무)", "should have p.p.는 '했어야 했는데 안 했다'", "have 뒤는 과거분사: must have went (×) → gone"],
          items: [
            b("The ground is wet. It ___ a lot.", "must have rained", ["must rain", "can't have rained", "should rain"], "과거에 대한 강한 추측: must have p.p.", ko: "땅이 젖었어요. 비가 많이 왔음에 틀림없어요."),
            b("I failed the test. I ___ harder.", "should have studied", ["must have studied", "can't have studied", "should study"], "과거 후회: should have p.p.", ko: "시험에 떨어졌어요. 더 열심히 공부했어야 했는데."),
            b("He was at home all day. He ___ the store.", "can't have robbed", ["must have robbed", "should have robbed", "may rob"], "과거 일의 부정 추측: can't have p.p.", ko: "그는 하루 종일 집에 있었어요. 그가 그 가게를 털었을 리가 없어요."),
            b("I can't find my keys. I ___ them on the bus.", "may have left", ["should have left", "can't have left", "must leave"], "과거에 대한 약한 추측: may have p.p.", ko: "열쇠를 못 찾겠어요. 버스에 두고 내렸을지도 몰라요."),
            b("She must have ___ the news already.", "heard", ["hear", "hearing", "to hear"], "조동사 + have + 과거분사"),
            b("You should have ___ me earlier.", "told", ["tell", "telling", "to tell"], "should have + 과거분사"),
            b("They can't have ___ so far.", "gone", ["went", "go", "going"], "can't have + 과거분사 (go – went – gone)"),
            b("We ___ have taken a taxi. We had plenty of time.", "needn't", ["must", "may", "could"], "need not have p.p.: ~할 필요가 없었는데", ko: "택시를 탈 필요가 없었는데. 시간이 충분했어요."),
            fx("He must have went home early.", "went", "gone", "have 뒤에는 과거분사: go – went – gone"),
            fx("You should have came to the party.", "came", "come", "have 뒤에는 과거분사: come – came – come"),
            fx("I may have leave my phone in the car.", "leave", "left", "have 뒤에는 과거분사: leave – left – left"),
            fx("She can't have say such a thing.", "say", "said", "have 뒤에는 과거분사: say – said – said"),
            ox("He might have missed the bus.", true, "might have p.p.: ~했을지도 모른다"),
            ox("I should have gone to bed earlier.", true, "should have p.p.: ~했어야 했는데"),
            ox("They must have be tired after the trip.", false, "have 뒤에는 과거분사: must have been"),
            rl("must have p.p.는 '~했음에 틀림없다'라는 과거에 대한 강한 추측이다.", true, "He must have been tired."),
            rl("should have p.p.는 '~해서 다행이다'라는 뜻이다.", false, "should have p.p.는 '~했어야 했는데(후회)'예요."),
            rl("can't have p.p.는 '~했을 리가 없다'라는 뜻이다.", true, "She can't have said that."),
            mn("You shouldn't have eaten so much.", "그렇게 많이 먹지 말았어야 했는데.", ["그렇게 많이 먹으면 안 돼요.", "그렇게 많이 먹었을 리가 없어요.", "그렇게 많이 먹었음에 틀림없어요."], "shouldn't have p.p.: ~하지 말았어야 했는데"),
